import { cardCls, cardTitleCls } from "../ui";

export default function Attachment({ data }: any) {
  const attachments = Array.isArray(data.attachments) ? data.attachments : [];
  function formatFileSize(bytes?: number) {
    if (bytes === undefined || bytes === null || Number.isNaN(Number(bytes)))
      return "";
    if (bytes < 1024) return `${bytes} B`;
    const kb = bytes / 1024;
    if (kb < 1024) return `${kb.toFixed(1)} KB`;
    const mb = kb / 1024;
    return `${mb.toFixed(1)} MB`;
  }

  if (attachments.length === 0) {
    return null;
  }

  return (
    <div className={`${cardCls} tw-mb-4 tw-p-5 tw-font-display`}>
      <h5 className={`${cardTitleCls} tw-mb-3 tw-text-center`}>Attachments</h5>
      <div className="tw-max-h-[200px] tw-overflow-y-auto">
        <ul className="tw-m-0 tw-flex tw-list-none tw-flex-col tw-p-0">
          {attachments.map((file: any, idx: number) => {
            const hasLink = Boolean(file.url);
            const fileName =
              file.original_name || file.file_name || "Attachment";
            return (
              <li
                key={file.id ?? file.file_name ?? file.original_name ?? idx}
                className={
                  idx !== attachments.length - 1
                    ? "tw-border-0 tw-border-b tw-border-solid tw-border-[#f0edf5]"
                    : ""
                }
              >
                <div className="tw-flex tw-items-start tw-gap-2.5 tw-py-2.5">
                  <svg
                    xmlns="http://www.w3.org/2000/svg"
                    width="18"
                    height="18"
                    fill="currentColor"
                    viewBox="0 0 16 16"
                    className="tw-mt-0.5 tw-shrink-0 tw-text-[#854ec9]"
                  >
                    <path d="M14 4.5V14a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V2a2 2 0 0 1 2-2h5.5zm-3 0A1.5 1.5 0 0 1 9.5 3V1H4a1 1 0 0 0-1 1v12a1 1 0 0 0 1 1h8a1 1 0 0 0 1-1V4.5z" />
                  </svg>
                  <div className="tw-min-w-0 tw-flex-1">
                    {hasLink ? (
                      <a
                        href={file.url}
                        target="_blank"
                        rel="noopener noreferrer"
                        title={fileName}
                        className="tw-block tw-truncate tw-text-[13.5px] tw-font-semibold tw-text-[#854ec9] tw-no-underline hover:tw-underline"
                      >
                        {fileName}
                      </a>
                    ) : (
                      <span
                        title={fileName}
                        className="tw-block tw-truncate tw-text-[13.5px] tw-font-semibold tw-text-[#14101c]"
                      >
                        {fileName}
                      </span>
                    )}
                    <div className="tw-mt-0.5 tw-text-[12px] tw-text-[#8a8398]">
                      {file.created_at && (
                        <span>
                          {new Date(file.created_at).toLocaleString("en-GB", {
                            year: "2-digit",
                            month: "2-digit",
                            day: "2-digit",
                            hour: "2-digit",
                            minute: "2-digit",
                          })}
                        </span>
                      )}
                      {file.size && (
                        <span>
                          {file.created_at ? " · " : null}
                          {formatFileSize(Number(file.size))}
                        </span>
                      )}
                    </div>
                  </div>
                </div>
              </li>
            );
          })}
        </ul>
      </div>
    </div>
  );
}
