import * as Sentry from "@sentry/nextjs";
import { useEffect, useState, useRef } from "react";
import { apiClient, ApiError } from "@/lib/apiClient";
import { cardCls, cardTitleCls } from "../ui";
import { primaryBtnCls, secondaryBtnCls, spinnerCls } from "@/components/tour-detail-page/ui";

export default function Conversation({
  referenceId,
  token,
}: {
  referenceId: string;
  token: string;
}) {
  const [newMessage, setNewMessage] = useState("");
  const [messages, setMessages] = useState([]);
  const [messagesLoading, setMessagesLoading] = useState(true);
  const [newmessageLoading, setNewMessageLoading] = useState(false);
  const [conversationFormErrors, setConversationFormErrors] = useState({});
  const [selectedFiles, setSelectedFiles] = useState<File[]>([]);
  const [activeTab, setActiveTab] = useState<"messages" | "contact">("messages");
  const fileInputRef = useRef<HTMLInputElement>(null);

  const messagesEndRef = useRef<HTMLDivElement>(null);

  // apiv3 token-kapsamlı konuşma (?token= ile sahibe açık); panel auth gerekmez.
  const fetchMessages = async () => {
    try {
      const data = await apiClient(
        `/bookings/${referenceId}/messages?token=${token}`,
      );
      setMessages(data.data);
    } catch (error) {
      Sentry.captureException(error);
    } finally {
      setMessagesLoading(false);
    }
  };

  const sendMessage = async () => {
    setConversationFormErrors({});

    try {
      setNewMessageLoading(true);
      const formData = new FormData();
      formData.append("message", newMessage);
      selectedFiles.forEach((file, idx) => {
        formData.append(`attachments[${idx}]`, file);
      });

      try {
        await apiClient(`/bookings/${referenceId}/messages?token=${token}`, {
          method: "POST",
          body: formData,
        });
      } catch (e) {
        if (e instanceof ApiError && e.status === 422) {
          throw e.errors ?? {};
        }
        throw {
          general: [
            `An unexpected error occurred (${e instanceof ApiError ? e.status : ""}). Please try again.`,
          ],
        };
      }

      setNewMessage("");
      setSelectedFiles([]);
      setMessagesLoading(true);
      await fetchMessages();
    } catch (error) {
      setConversationFormErrors(error as object);
    } finally {
      setNewMessageLoading(false);
    }
  };

  useEffect(() => {
    fetchMessages();
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    if (messagesEndRef.current) {
      const node = messagesEndRef.current as HTMLDivElement;
      node.scrollTop = node.scrollHeight;
    }
  }, [messages]);

  const PaperclipIcon = ({ size = 18 }: { size?: number }) => (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      fill="currentColor"
      viewBox="0 0 16 16"
    >
      <path d="M14 4.5V14a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V2a2 2 0 0 1 2-2h5.5zm-3 0A1.5 1.5 0 0 1 9.5 3V1H4a1 1 0 0 0-1 1v12a1 1 0 0 0 1 1h8a1 1 0 0 0 1-1V4.5z" />
    </svg>
  );

  if (messagesLoading) {
    return (
      <div className={`${cardCls} tw-mb-4 tw-p-5 tw-font-display`}>
        <h5 className={`${cardTitleCls} tw-mb-3 tw-text-center`}>Conversation</h5>
        <div className="tw-flex tw-h-[300px] tw-flex-col tw-items-center tw-justify-center tw-gap-3 tw-text-[#5d556c]">
          <span className="tw-inline-block tw-h-8 tw-w-8 tw-animate-spin tw-rounded-full tw-border-4 tw-border-solid tw-border-[#854ec9] tw-border-r-transparent" />
          <p className="tw-m-0 tw-text-sm">Loading messages...</p>
        </div>
      </div>
    );
  }

  const tabBtnCls = (active: boolean) =>
    `tw-flex-1 tw-border-0 tw-border-b-2 tw-border-solid tw-bg-transparent tw-px-3 tw-py-2.5 tw-text-[14px] tw-font-semibold tw-cursor-pointer tw-transition-colors ${
      active
        ? "tw-border-[#854ec9] tw-text-[#854ec9]"
        : "tw-border-transparent tw-text-[#8a8398] hover:tw-text-[#2a2336]"
    }`;

  return (
    <div className={`${cardCls} tw-mb-4 tw-p-5 tw-font-display`}>
      <h5 className={`${cardTitleCls} tw-mb-3 tw-text-center`}>Conversation</h5>

      <div className="tw-mb-3 tw-flex tw-border-0 tw-border-b tw-border-solid tw-border-[#ece9f1]">
        <button
          type="button"
          className={tabBtnCls(activeTab === "messages")}
          onClick={() => setActiveTab("messages")}
        >
          Messages
        </button>
        <button
          type="button"
          className={tabBtnCls(activeTab === "contact")}
          onClick={() => setActiveTab("contact")}
        >
          Contact
        </button>
      </div>

      {activeTab === "messages" ? (
        <div>
          <div
            ref={messagesEndRef}
            className="tw-mb-3 tw-max-h-[400px] tw-min-h-[200px] tw-overflow-y-auto tw-rounded-xl tw-bg-[#f7f5fb] tw-px-2 tw-py-4"
          >
            {messages.length === 0 ? (
              <div className="tw-mt-10 tw-text-center tw-text-[15px] tw-text-[#8a8398]">
                No messages yet.
              </div>
            ) : (
              messages.map((message: any) => {
                const isCustomer = message.sender_type === "customer";
                const attachments = Array.isArray(message.attachments)
                  ? message.attachments
                  : [];
                return (
                  <div
                    key={message.id}
                    className={`tw-mb-3 tw-flex ${
                      isCustomer ? "tw-justify-end" : "tw-justify-start"
                    }`}
                  >
                    <div
                      className={`tw-max-w-[75%] tw-px-4 tw-py-2.5 tw-text-left tw-shadow-[0_1px_4px_rgba(20,16,28,0.07)] ${
                        isCustomer
                          ? "tw-rounded-[16px_16px_4px_16px] tw-bg-[#efe7fb] tw-text-[#2a2336]"
                          : "tw-rounded-[16px_16px_16px_4px] tw-bg-white tw-text-[#2a2336] tw-border tw-border-solid tw-border-[#ece9f1]"
                      }`}
                    >
                      <div className="tw-break-words tw-text-[14px]">
                        {message.message}
                      </div>
                      {attachments.length > 0 && (
                        <div className="tw-mt-2 tw-border-0 tw-border-t tw-border-solid tw-border-[#e3e3ec] tw-pt-2">
                          <div className="tw-mb-1 tw-flex tw-items-center tw-gap-1.5 tw-text-[12px] tw-font-medium tw-text-[#6b6577]">
                            <PaperclipIcon size={14} />
                            Attachments
                          </div>
                          <ul className="tw-m-0 tw-flex tw-list-none tw-flex-col tw-gap-1 tw-p-0">
                            {attachments.map((file: any) => {
                              const hasLink = Boolean(file.url);
                              const name =
                                file.original_name ||
                                file.file_name ||
                                "Attachment";
                              return (
                                <li
                                  key={
                                    file.id ??
                                    file.file_name ??
                                    file.original_name
                                  }
                                  className="tw-flex tw-items-center tw-gap-1.5"
                                >
                                  <PaperclipIcon size={14} />
                                  {hasLink ? (
                                    <a
                                      href={file.url}
                                      target="_blank"
                                      rel="noopener noreferrer"
                                      title={name}
                                      className="tw-max-w-[140px] tw-truncate tw-text-[12.5px] tw-font-medium tw-text-[#854ec9] tw-no-underline hover:tw-underline"
                                    >
                                      {name}
                                    </a>
                                  ) : (
                                    <span
                                      title={name}
                                      className="tw-max-w-[140px] tw-truncate tw-text-[12.5px] tw-font-medium tw-text-[#312d45]"
                                    >
                                      {name}
                                    </span>
                                  )}
                                </li>
                              );
                            })}
                          </ul>
                        </div>
                      )}
                      <div
                        className={`tw-mt-1 tw-text-[11px] tw-text-[#9b95a8] ${
                          isCustomer ? "tw-text-right" : "tw-text-left"
                        }`}
                      >
                        {message.name}
                        {message.created_at && (
                          <span className="tw-ml-2">
                            {new Date(message.created_at).toLocaleString(
                              "en-GB",
                              {
                                year: "2-digit",
                                month: "2-digit",
                                day: "2-digit",
                                hour: "2-digit",
                                minute: "2-digit",
                              },
                            )}
                          </span>
                        )}
                      </div>
                    </div>
                  </div>
                );
              })
            )}
          </div>

          <textarea
            value={newMessage ?? ""}
            onChange={(event) => setNewMessage(event.target.value)}
            placeholder="Write a message"
            className="tw-min-h-[100px] tw-w-full tw-rounded-[10px] tw-border tw-border-solid tw-border-[#d8d2e1] tw-px-3.5 tw-py-2.5 tw-text-[14px] tw-text-[#14101c] tw-outline-none focus:tw-border-[#854ec9] placeholder:tw-text-[#8a8398]"
          />

          <div className="tw-mt-2 tw-flex tw-items-center tw-justify-end tw-gap-2">
            <input
              type="file"
              multiple
              accept=".pdf,.png,.jpg,.jpeg,.doc,.docx,.xls,.xlsx"
              className="tw-hidden"
              ref={fileInputRef}
              onChange={(e) => {
                const files = Array.from(e.target.files || []);
                const allowedTypes = [
                  "application/pdf",
                  "image/png",
                  "image/jpeg",
                  "application/msword",
                  "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
                  "application/vnd.ms-excel",
                  "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                ];
                const filtered = files.filter((file) =>
                  allowedTypes.includes(file.type),
                );
                const total = [...selectedFiles, ...filtered].slice(0, 3);
                setSelectedFiles(total);
                if (fileInputRef.current) fileInputRef.current.value = "";
              }}
            />
            <button
              type="button"
              className={secondaryBtnCls}
              onClick={() => fileInputRef.current?.click()}
              disabled={selectedFiles.length >= 3}
            >
              <PaperclipIcon size={16} />
              Attachment
            </button>
            <button
              type="button"
              className={primaryBtnCls}
              onClick={() => sendMessage()}
              disabled={newmessageLoading || !newMessage.trim()}
            >
              {newmessageLoading ? (
                <>
                  <span className={spinnerCls} />
                  Sending...
                </>
              ) : (
                <>
                  <svg
                    xmlns="http://www.w3.org/2000/svg"
                    width="15"
                    height="15"
                    fill="currentColor"
                    viewBox="0 0 16 16"
                  >
                    <path d="M15.964.686a.5.5 0 0 0-.65-.65L.767 5.855H.766l-.452.18a.5.5 0 0 0-.082.887l.41.26.001.002 4.995 3.178 3.178 4.995.002.002.26.41a.5.5 0 0 0 .886-.083zm-1.833 1.89L6.637 10.07l-.215-.338a.5.5 0 0 0-.154-.154l-.338-.215 7.494-7.494 1.178-.471z" />
                  </svg>
                  Send Message
                </>
              )}
            </button>
          </div>

          {selectedFiles.length > 0 && (
            <div className="tw-mt-2 tw-flex tw-flex-col tw-items-end tw-gap-1.5">
              {selectedFiles.map((file, idx) => (
                <div
                  key={idx}
                  className="tw-flex tw-items-center tw-gap-2 tw-rounded-[8px] tw-border tw-border-solid tw-border-[#ece9f1] tw-bg-[#f7f5fb] tw-px-2.5 tw-py-1.5 tw-text-[13px] tw-text-[#312d45]"
                >
                  <PaperclipIcon size={15} />
                  <span
                    title={file.name}
                    className="tw-max-w-[140px] tw-truncate tw-font-medium"
                  >
                    {file.name}
                  </span>
                  <span className="tw-text-[11px] tw-text-[#8a8398]">
                    {file.size < 1024
                      ? file.size + " B"
                      : file.size < 1024 * 1024
                        ? (file.size / 1024).toFixed(1) + " KB"
                        : (file.size / 1024 / 1024).toFixed(1) + " MB"}
                  </span>
                  <button
                    type="button"
                    onClick={() =>
                      setSelectedFiles(
                        selectedFiles.filter((_, i) => i !== idx),
                      )
                    }
                    title="Remove"
                    className="tw-border-0 tw-bg-transparent tw-text-[16px] tw-leading-none tw-text-[#b23838] tw-cursor-pointer"
                  >
                    ×
                  </button>
                </div>
              ))}
            </div>
          )}
        </div>
      ) : (
        <div className="tw-px-1 tw-py-2 tw-text-[14px] tw-leading-relaxed tw-text-[#3f3a4d]">
          If you have any inquiries for TravelShop Booking, please feel free to
          reach out to us at{" "}
          <a
            href="mailto:help@travelshopbooking.com"
            className="tw-font-semibold tw-text-[#854ec9] tw-no-underline hover:tw-underline"
          >
            help@travelshopbooking.com
          </a>
          . Our team of experienced consultants will respond to you promptly.
        </div>
      )}

      {Object.keys(conversationFormErrors).length > 0 && (
        <div className="tw-mt-3 tw-rounded-[10px] tw-bg-[#fdecec] tw-px-3 tw-py-2.5 tw-text-[13px] tw-text-[#b23838]">
          <p className="tw-m-0 tw-mb-1 tw-font-semibold">
            Please check the following errors:
          </p>
          <ul className="tw-m-0 tw-pl-4">
            {Object.entries(conversationFormErrors).map(([field, errors]) =>
              Array.isArray(errors)
                ? errors.map((error: any, index: number) => (
                    <li key={`${field}-${index}`}>{error}</li>
                  ))
                : null,
            )}
          </ul>
        </div>
      )}
    </div>
  );
}
