import priceFormat from "@/helpers/priceFormat";
import { cardCls, cardTitleCls } from "../ui";
import { primaryBtnCls, outlineBtnCls } from "@/components/tour-detail-page/ui";

export default function PaymentDetails({
  data,
  referenceId,
  onViewDetails,
}: {
  data: any;
  referenceId: string;
  onViewDetails: () => void;
}) {
  if (data.amounts.buyer.final_amount <= 0) {
    return null;
  }

  const fmt = (amount: number) =>
    priceFormat({
      amount,
      currency: data.buyer_currency,
      maximumFractionDigits: 2,
    });

  const rowCls =
    "tw-flex tw-justify-between tw-gap-3 tw-py-2 tw-border-0 tw-border-b tw-border-solid tw-border-[#f0edf5] tw-text-[13.5px]";

  return (
    <div className={`${cardCls} tw-mb-4 tw-p-5 tw-font-display`}>
      <h5 className={`${cardTitleCls} tw-mb-3 tw-text-center`}>
        Payment Details
      </h5>

      <div>
        {data.amounts.buyer.original_amount != data.amounts.buyer.final_amount && (
          <div className={rowCls}>
            <span className="tw-text-[#6b6577]">Total Amount</span>
            <span className="tw-font-medium tw-text-[#14101c]">
              {fmt(data.amounts.buyer.original_amount)}
            </span>
          </div>
        )}
        {data.amounts.buyer.discount_amount > 0 && (
          <div className={rowCls}>
            <span className="tw-text-[#b23838]">Discounts</span>
            <span className="tw-font-medium tw-text-[#b23838]">
              - {fmt(data.amounts.buyer.discount_amount)}
            </span>
          </div>
        )}
        {data.amounts.buyer.coupon_amount > 0 && (
          <div className={rowCls}>
            <span className="tw-text-[#b23838]">Promo Code Discount</span>
            <span className="tw-font-medium tw-text-[#b23838]">
              - {fmt(data.amounts.buyer.coupon_amount)}
            </span>
          </div>
        )}
        <div className={rowCls}>
          <span className="tw-text-[#6b6577]">Amount to Pay</span>
          <span className="tw-font-medium tw-text-[#14101c]">
            {fmt(data.amounts.buyer.final_amount)}
          </span>
        </div>
        {data.paid_amount > 0 && (
          <div className={rowCls}>
            <span className="tw-text-[#1f8a4c]">Amount Paid</span>
            <span className="tw-font-medium tw-text-[#1f8a4c]">
              {fmt(data.amounts.buyer.paid_amount)}
            </span>
          </div>
        )}
        {data.amounts.buyer.remaining_amount > 0 && (
          <div className="tw-flex tw-justify-between tw-gap-3 tw-py-2.5 tw-text-[15px]">
            <span className="tw-font-bold tw-text-[#14101c]">
              Remaining Amount
            </span>
            <span className="tw-font-bold tw-text-[#854ec9]">
              {fmt(data.amounts.buyer.remaining_amount)}
            </span>
          </div>
        )}
      </div>

      <div className="tw-mt-3 tw-flex tw-flex-col tw-gap-2">
        {data.amounts.buyer.remaining_amount > 0 && (
          <a
            href={"/booking/" + referenceId + "/payment?token=" + data.token}
            className={`${primaryBtnCls} tw-w-full`}
          >
            Continue to Payment
          </a>
        )}
        <button
          type="button"
          onClick={onViewDetails}
          className={`${outlineBtnCls} tw-w-full`}
        >
          View Payment Details
        </button>
      </div>
    </div>
  );
}
