"use client";
import { useState, useEffect } from "react";
import { applyPromotion } from "@/services/booking/applyPromotion";
import { cardCls, cardTitleCls, promoPillCls } from "../ui";
import { spinnerCls } from "@/components/tour-detail-page/ui";

export default function Promotions({
  data,
  referenceId,
}: {
  data: any;
  referenceId: string;
}) {
  const promotions = Array.isArray(data.promotions) ? data.promotions : [];
  const [loadingPromoId, setLoadingPromoId] = useState<number | null>(null);
  const [successMessage, setSuccessMessage] = useState<string>("");
  const [errorMessage, setErrorMessage] = useState<string>("");
  const [timers, setTimers] = useState<{ [key: number]: string }>({});

  useEffect(() => {
    const interval = setInterval(() => {
      const newTimers: { [key: number]: string } = {};

      promotions.forEach((promo: any) => {
        if (promo.status.toLowerCase() === "active" && promo.expiration_at) {
          const now = new Date().getTime();
          const expiration = new Date(promo.expiration_at).getTime();
          const remaining = expiration - now;

          if (remaining > 0) {
            const hours = Math.floor(
              (remaining % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60),
            );
            const minutes = Math.floor(
              (remaining % (1000 * 60 * 60)) / (1000 * 60),
            );
            const seconds = Math.floor((remaining % (1000 * 60)) / 1000);

            newTimers[promo.id] = `${hours}h ${minutes}m ${seconds}s`;
          } else {
            newTimers[promo.id] = "Expired";
          }
        }
      });

      setTimers(newTimers);
    }, 1000);

    return () => clearInterval(interval);
  }, [promotions]);

  const formatDate = (dateString: string) => {
    if (!dateString) return "";
    return new Date(dateString).toLocaleString("en-GB", {
      year: "2-digit",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
    });
  };

  const handleApply = async (promotionCode: string, promoId: number) => {
    setLoadingPromoId(promoId);
    setSuccessMessage("");
    setErrorMessage("");

    try {
      const response = await applyPromotion(
        referenceId,
        promotionCode,
        data.token,
      );
      setSuccessMessage(response.message || "Promotion applied successfully!");
      setTimeout(() => {
        window.location.reload();
      }, 1500);
    } catch (error: any) {
      const message =
        error.response?.message ||
        error.message ||
        "Failed to apply promotion. Please try again.";
      setErrorMessage(message);
    } finally {
      setLoadingPromoId(null);
    }
  };

  const banner = (
    tone: "success" | "error",
    message: string,
    onClose: () => void,
  ) => (
    <div
      className={`tw-mb-3 tw-flex tw-items-start tw-justify-between tw-gap-2 tw-rounded-[10px] tw-px-3 tw-py-2 tw-text-[12.5px] ${
        tone === "success"
          ? "tw-bg-[#eafaf0] tw-text-[#1f8a4c]"
          : "tw-bg-[#fdecec] tw-text-[#b23838]"
      }`}
    >
      <span>{message}</span>
      <button
        type="button"
        onClick={onClose}
        aria-label="Close"
        className="tw-shrink-0 tw-border-0 tw-bg-transparent tw-cursor-pointer tw-text-current tw-leading-none"
      >
        ×
      </button>
    </div>
  );

  return (
    <div className={`${cardCls} tw-mb-4 tw-p-5 tw-font-display`}>
      <h5 className={`${cardTitleCls} tw-mb-3 tw-text-center`}>Promotions</h5>

      {successMessage &&
        banner("success", successMessage, () => setSuccessMessage(""))}
      {errorMessage && banner("error", errorMessage, () => setErrorMessage(""))}

      {promotions.length === 0 ? (
        <div className="tw-py-3 tw-text-center tw-text-[13.5px] tw-text-[#8a8398]">
          No promotions.
        </div>
      ) : (
        <div className="tw-max-h-[250px] tw-overflow-y-auto">
          <ul className="tw-m-0 tw-flex tw-list-none tw-flex-col tw-p-0">
            {promotions.map((promo: any, idx: number) => (
              <li
                key={promo.id ?? idx}
                className={
                  idx !== promotions.length - 1
                    ? "tw-border-0 tw-border-b tw-border-solid tw-border-[#f0edf5] tw-pb-3"
                    : ""
                }
              >
                <div className="tw-flex tw-flex-col tw-gap-2 tw-py-3">
                  <div className="tw-flex tw-items-center tw-justify-between tw-gap-2">
                    <span className="tw-font-mono tw-text-[14px] tw-font-semibold tw-text-[#14101c]">
                      {promo.promotion_code}
                    </span>
                    <span className={promoPillCls(promo.status)}>
                      {promo.status?.toUpperCase()}
                    </span>
                  </div>

                  <div className="tw-flex tw-items-center tw-justify-between tw-gap-2">
                    <span className="tw-text-[15px] tw-font-bold tw-text-[#854ec9]">
                      {promo.amount} {promo.currency}
                    </span>
                    {promo.status.toLowerCase() === "active" && (
                      <button
                        type="button"
                        onClick={() =>
                          handleApply(promo.promotion_code, promo.id)
                        }
                        disabled={loadingPromoId !== null}
                        className="tw-min-w-[70px] tw-rounded-full tw-border-0 tw-bg-[#854ec9] tw-px-4 tw-py-1.5 tw-text-[12.5px] tw-font-semibold tw-text-white tw-cursor-pointer hover:tw-bg-[#6a3da4] disabled:tw-opacity-60 tw-transition-colors"
                      >
                        {loadingPromoId === promo.id ? (
                          <span className={spinnerCls} />
                        ) : (
                          "Apply"
                        )}
                      </button>
                    )}
                  </div>

                  {promo.status.toLowerCase() === "active" &&
                    promo.expiration_at && (
                      <>
                        <div className="tw-flex tw-items-center tw-gap-2 tw-rounded-[8px] tw-border tw-border-solid tw-border-[#ffd66b] tw-bg-[#fff8e6] tw-px-3 tw-py-2">
                          <span className="tw-text-[18px]">⏱️</span>
                          <div>
                            <p className="tw-m-0 tw-text-[11px] tw-font-medium tw-text-[#9a7b1f]">
                              Limited Time Offer
                            </p>
                            <p className="tw-m-0 tw-font-mono tw-text-[14px] tw-font-bold tw-text-[#e0603b]">
                              {timers[promo.id] || "Calculating..."}
                            </p>
                          </div>
                        </div>
                        <div className="tw-text-[12px] tw-text-[#8a8398]">
                          Expires: {formatDate(promo.expiration_at)}
                        </div>
                      </>
                    )}

                  {promo.expiration_at &&
                    promo.status.toLowerCase() !== "active" && (
                      <div className="tw-text-[12px] tw-text-[#8a8398]">
                        Expires: {formatDate(promo.expiration_at)}
                      </div>
                    )}

                  {promo.created_at && (
                    <div className="tw-text-[11px] tw-text-[#b0aaba]">
                      Created: {formatDate(promo.created_at)}
                    </div>
                  )}
                </div>
              </li>
            ))}
          </ul>
        </div>
      )}
    </div>
  );
}
