import { cardCls, statusPillCls, paymentPillCls } from "../ui";

export default function StatusSummary({ data }: any) {
  const labelCls = "tw-m-0 tw-text-[12px] tw-font-semibold tw-uppercase tw-tracking-wide tw-text-[#8a8398]";

  return (
    <div className="tw-mb-4 tw-grid tw-grid-cols-2 tw-gap-3 lg:tw-grid-cols-4">
      <div className={`${cardCls} tw-p-4`}>
        <p className={labelCls}>Type</p>
        <p className="tw-m-0 tw-mt-1 tw-text-[14px] tw-font-semibold tw-text-[#14101c]">
          {data.record_type_label || "-"}
        </p>
      </div>
      <div className={`${cardCls} tw-p-4`}>
        <p className={labelCls}>Reference No</p>
        <p className="tw-m-0 tw-mt-1 tw-text-[14px] tw-font-semibold tw-text-[#14101c]">
          {data.reference_id || "-"}
        </p>
      </div>
      <div className={`${cardCls} tw-p-4`}>
        <p className={labelCls}>Status</p>
        <p className="tw-m-0 tw-mt-1.5">
          <span className={statusPillCls(data.booking_status)}>
            {data.booking_status_label || "-"}
          </span>
        </p>
      </div>
      <div className={`${cardCls} tw-p-4`}>
        <p className={labelCls}>Payment Status</p>
        <p className="tw-m-0 tw-mt-1.5">
          {data.payment_status ? (
            <span className={paymentPillCls(data.payment_status)}>
              {data.payment_status_label}
            </span>
          ) : (
            <span className="tw-text-[#8a8398]">—</span>
          )}
        </p>
      </div>
    </div>
  );
}
