import priceFormat from "@/helpers/priceFormat";
import { primaryBtnCls, outlineBtnCls } from "@/components/tour-detail-page/ui";

export default function MobileFooterSticky({
  data,
  onViewDetails,
}: {
  data: any;
  onViewDetails: () => void;
}) {
  if (data.amounts.buyer.remaining_amount == 0) {
    return null;
  }

  return (
    <div
      className="tw-fixed tw-inset-x-0 tw-bottom-0 tw-z-[1040] tw-flex tw-items-center tw-gap-3 tw-bg-white tw-px-3 tw-py-2.5 tw-font-display lg:tw-hidden"
      style={{ boxShadow: "0 -2px 16px rgba(133, 78, 201, .18)" }}
    >
      <div className="tw-shrink-0">
        <div className="tw-text-[12px] tw-text-[#8a8398]">Remaining Amount</div>
        <span className="tw-text-[24px] tw-font-bold tw-text-[#854ec9]">
          {priceFormat({
            amount: data.amounts.buyer.remaining_amount,
            currency: data.buyer_currency,
          })}
        </span>
      </div>
      <div className="tw-ml-auto tw-flex tw-flex-col tw-items-stretch tw-gap-1.5">
        <a
          href={"/booking/" + data.reference_id + "/payment?token=" + data.token}
          className={`${primaryBtnCls} tw-py-2`}
        >
          Continue to Payment
        </a>
        <button
          type="button"
          onClick={onViewDetails}
          className={`${outlineBtnCls} tw-py-1.5`}
        >
          View Payment Details
        </button>
      </div>
    </div>
  );
}
