import { apiClient, ApiError } from "@/lib/apiClient";

// apiv3 token-kapsamlı traveler güncelleme (POST /bookings/{ref}/travelers?token=).
// Çağıran bileşen 422'de doğrudan errors nesnesini, diğer hatalarda {general:[...]} bekliyor.
export default async function postTravelerUpdate({
  requestParameters,
  reference_id,
  token,
}: {
  requestParameters: any;
  reference_id: string;
  token: string;
}) {
  try {
    return await apiClient(
      `/bookings/${reference_id}/travelers?token=${token}`,
      { method: "POST", body: requestParameters }
    );
  } catch (e) {
    if (e instanceof ApiError && e.status === 422) {
      throw e.errors ?? {};
    }
    throw {
      general: [
        "An error occurred while processing your booking. Please try again later.",
      ],
    };
  }
}
