import Image from "next/image";
import { cardCls } from "../ui";
import { outlineBtnCls } from "@/components/tour-detail-page/ui";
import { formatPlainDate, addPlainDays } from "@/helpers/plainDate";

export default function TripDetails({ data, referenceId }: any) {
  // Tarih saat dilimi kaymasına karşı güvenli biçimlendirilir (bkz. helpers/plainDate.ts).
  const getFullDate = (date: string | Date) => formatPlainDate(date);

  const Row = ({ label, children }: { label: string; children: React.ReactNode }) => (
    <div className="tw-flex tw-justify-between tw-gap-3 tw-py-2 tw-border-0 tw-border-b tw-border-solid tw-border-[#f0edf5] tw-text-[13.5px]">
      <span className="tw-text-[#6b6577]">{label}</span>
      <span className="tw-text-right tw-font-medium tw-text-[#14101c]">
        {children}
      </span>
    </div>
  );

  // Veri olmayan satırları hiç gösterme (boş lokasyon/tarih/pax çöp görünmesin).
  const durationDays = Number(data.tour?.duration_days) || 0;
  const startsIn = [data.tour?.start_location, data.start_date ? getFullDate(data.start_date) : ""]
    .filter(Boolean)
    .join(", ");
  const endDateStr = data.start_date
    ? durationDays > 1
      ? getFullDate(addPlainDays(data.start_date, durationDays - 1))
      : getFullDate(data.start_date)
    : "";
  const endsIn = [data.tour?.end_location, endDateStr].filter(Boolean).join(", ");
  const hasPax = data.pax !== null && data.pax !== undefined && data.pax !== "";

  return (
    <div className={`${cardCls} tw-mb-4 tw-overflow-hidden tw-font-display`}>
      {/* Full-bleed tour header image */}
      <div className="tw-relative tw-h-[180px] tw-w-full tw-bg-[#f0eef4]">
        {data.tour.image ? (
          <Image
            src={data.tour.image}
            alt={data.tour.name || data.subject}
            fill
            sizes="(max-width: 1024px) 100vw, 320px"
            quality={90}
            className="tw-object-cover"
          />
        ) : (
          <div
            className="tw-h-full tw-w-full"
            style={{
              background: "linear-gradient(135deg, #854ec9, #6a3da4)",
            }}
          />
        )}
        <div
          className="tw-absolute tw-inset-0"
          style={{
            background:
              "linear-gradient(to top, rgba(20,16,28,0.55) 0%, rgba(20,16,28,0) 45%)",
          }}
        />
        {data.service_type === "private" && (
          <span className="tw-absolute tw-left-3 tw-top-3 tw-inline-flex tw-items-center tw-rounded-full tw-bg-white/95 tw-px-2.5 tw-py-1 tw-text-[11px] tw-font-bold tw-uppercase tw-tracking-[0.04em] tw-text-[#854ec9] tw-backdrop-blur">
            Private Tour
          </span>
        )}
        <span className="tw-absolute tw-bottom-3 tw-left-4 tw-text-[11px] tw-font-bold tw-uppercase tw-tracking-[0.12em] tw-text-white/85">
          Trip Details
        </span>
      </div>

      <div className="tw-p-5">
        {startsIn && <Row label="Starts in">{startsIn}</Row>}
        {endsIn && <Row label="Ends in">{endsIn}</Row>}
        {durationDays > 0 && <Row label="Duration">{durationDays} Days</Row>}
        {hasPax && (
          <Row label="Pax">
            {`${data.pax} ${data.pax === 1 ? "traveler" : "travelers"}`}
          </Row>
        )}
        {data.service_type && (
          <Row label="Service Type">{data.service_type_label}</Row>
        )}
        {data.tour?.departure_type && (
          <Row label="Departure Type">{data.tour.departure_type}</Row>
        )}
        {data.company?.name && <Row label="Tour Owner">{data.company.name}</Row>}

        <a
          href={"/booking/" + referenceId + "/tour?token=" + data.token}
          className={`${outlineBtnCls} tw-mt-4 tw-w-full`}
        >
          View Trip Details
        </a>
      </div>
    </div>
  );
}
