import { useEffect, useState } from "react";
import Select from "react-select";
import getLocations from "@/services/locations";
import postTravelerUpdate from "@/services/booking/travelerUpdate";
import Modal from "@/components/tour-detail-page/modal";
import { bookingSelectStyles, SelectOption } from "../ui";
import {
  inputCls,
  labelCls,
  primaryBtnCls,
  secondaryBtnCls,
  dangerAlertCls,
} from "@/components/tour-detail-page/ui";

export default function TravelerDetailsModal({
  data,
  open,
  onClose,
}: {
  data: any;
  open: boolean;
  onClose: () => void;
}) {
  const [travelerDetailsFormErrors, setTravelerDetailsFormErrors] = useState<{
    [key: string]: string[];
  }>({});
  const [openRow, setOpenRow] = useState(0);
  const [model, setModel] = useState(() => {
    const updatedTravelers = data.travelers.map((traveler: any) => {
      if (traveler.birth_date) {
        const [year, month, day] = traveler.birth_date.split("-");
        return {
          ...traveler,
          dob_year: parseInt(year, 10),
          dob_month: parseInt(month, 10),
          dob_day: parseInt(day, 10),
        };
      }
      return traveler;
    });

    return { ...data, travelers: updatedTravelers };
  });

  const [locations, setLocations] = useState([
    { id: 0, name: "", phone_code: "" },
  ]);

  const [loading, setLoading] = useState(true);

  const fetchLocations = async () => {
    await getLocations().then((res) => {
      setLoading(false);
      setLocations(res);
    });
  };

  const changeCustomerValue = ({
    customer,
    name,
    value,
  }: {
    customer: any;
    name: string;
    value: string;
  }) => {
    var newCustomers: any = JSON.parse(JSON.stringify(model.travelers));
    newCustomers[customer][name] = value;
    setModel({ ...model, travelers: newCustomers });
  };

  const submitForm = async () => {
    setLoading(true);
    setTravelerDetailsFormErrors({});

    await postTravelerUpdate({
      reference_id: model.reference_id,
      token: model.token,
      requestParameters: {
        travelers: model.travelers.map((customer: any) => {
          return {
            ...customer,
            phone_code: customer.phone ? customer.phone_code : null,
            date_of_birth:
              customer.dob_year > 0 &&
              customer.dob_month > 0 &&
              customer.dob_day > 0
                ? [
                    String(customer.dob_year).padStart(4, "0"),
                    String(customer.dob_month).padStart(2, "0"),
                    String(customer.dob_day).padStart(2, "0"),
                  ].join("-")
                : null,
          };
        }),
      },
    })
      .then((res) => {
        window.location.href =
          "/booking/" + model.reference_id + "?token=" + model.token;
      })
      .catch((error) => {
        setTravelerDetailsFormErrors(error);
        window.scrollTo({ top: 0, behavior: "smooth" });
        setLoading(false);
      });
  };

  useEffect(() => {
    fetchLocations();
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  const sortedLocations = [...locations].sort((a, b) =>
    a.name < b.name ? -1 : a.name > b.name ? 1 : 0,
  );

  const nationalityOptions: SelectOption[] = sortedLocations.map((i: any) => ({
    value: i.id,
    label: i.name,
  }));
  const phoneCodeOptions: SelectOption[] = sortedLocations
    .filter((i: any) => i.phone_code && i.phone_code !== "")
    .map((i: any) => ({ value: i.id, label: `${i.name} (${i.phone_code})` }));

  const portalTarget =
    typeof document !== "undefined" ? document.body : undefined;

  const req = <span className="tw-text-[#b23838]">*</span>;

  return (
    <Modal
      open={open}
      onClose={onClose}
      title="Traveler Details"
      size="lg"
      staticBackdrop
      footer={
        <>
          <button type="button" className={secondaryBtnCls} onClick={onClose}>
            Close
          </button>
          <button
            type="button"
            className={primaryBtnCls}
            onClick={submitForm}
            disabled={loading}
          >
            Save Changes
          </button>
        </>
      }
    >
      <div className="tw-font-display">
        {loading && (
          <div className="tw-flex tw-flex-col tw-items-center tw-gap-3 tw-py-12 tw-text-[#5d556c]">
            <span className="tw-inline-block tw-h-8 tw-w-8 tw-animate-spin tw-rounded-full tw-border-4 tw-border-solid tw-border-[#854ec9] tw-border-r-transparent" />
            <p className="tw-m-0 tw-text-sm">Please wait...</p>
          </div>
        )}

        {!loading && (
          <>
            {Object.keys(travelerDetailsFormErrors).length > 0 && (
              <div className={dangerAlertCls}>
                <p className="tw-m-0 tw-mb-1 tw-font-semibold">
                  Please check the following errors:
                </p>
                <ul className="tw-m-0 tw-pl-4">
                  {Object.entries(travelerDetailsFormErrors).map(
                    ([field, errors]) =>
                      errors.map((error, index) => (
                        <li key={`${field}-${index}`}>{error}</li>
                      )),
                  )}
                </ul>
              </div>
            )}

            <div className="tw-flex tw-flex-col tw-gap-3">
              {model.travelers.map((customer: any, row: number) => {
                const isOpen = openRow === row;
                const label =
                  row === 0
                    ? "Lead Traveler / Contact Person"
                    : `Traveler ${row + 1}`;

                return (
                  <div
                    key={row}
                    className="tw-overflow-hidden tw-rounded-xl tw-border tw-border-solid tw-border-[#ece9f1]"
                  >
                    <button
                      type="button"
                      onClick={() => setOpenRow(isOpen ? -1 : row)}
                      className={`tw-flex tw-w-full tw-items-center tw-justify-between tw-gap-3 tw-border-0 tw-px-4 tw-py-3 tw-text-left tw-cursor-pointer tw-transition-colors ${
                        isOpen ? "tw-bg-[#f5f0fc]" : "tw-bg-[#faf9fc] hover:tw-bg-[#f5f0fc]"
                      }`}
                    >
                      <span className="tw-text-[14px] tw-text-[#2a2336]">
                        {req}{" "}
                        <strong className="tw-font-semibold">{label}:</strong>{" "}
                        {customer.first_name} {customer.last_name}
                      </span>
                      <svg
                        width="16"
                        height="16"
                        viewBox="0 0 16 16"
                        fill="currentColor"
                        className={`tw-shrink-0 tw-text-[#854ec9] tw-transition-transform ${
                          isOpen ? "tw-rotate-180" : ""
                        }`}
                      >
                        <path d="M1.646 4.646a.5.5 0 0 1 .708 0L8 10.293l5.646-5.647a.5.5 0 0 1 .708.708l-6 6a.5.5 0 0 1-.708 0l-6-6a.5.5 0 0 1 0-.708" />
                      </svg>
                    </button>

                    {isOpen && (
                      <div className="tw-border-0 tw-border-t tw-border-solid tw-border-[#ece9f1] tw-p-4">
                        <div className="tw-grid tw-grid-cols-1 tw-gap-4 md:tw-grid-cols-3">
                          <div>
                            <span className={labelCls}>
                              Title {row === 0 && req}
                            </span>
                            <div className="tw-flex tw-flex-wrap tw-gap-3">
                              {["Mr.", "Mrs.", "Ms."].map((title) => (
                                <label
                                  key={title}
                                  className="tw-inline-flex tw-items-center tw-gap-1.5 tw-text-[14px] tw-text-[#2a2336] tw-cursor-pointer"
                                >
                                  <input
                                    type="radio"
                                    className="tw-accent-[#854ec9]"
                                    value={title}
                                    checked={title === customer.title}
                                    onChange={(e) =>
                                      changeCustomerValue({
                                        customer: row,
                                        name: "title",
                                        value: e.target.value,
                                      })
                                    }
                                  />
                                  {title}
                                </label>
                              ))}
                            </div>
                          </div>
                          <div>
                            <label className={labelCls}>
                              First Name {row === 0 && req}
                            </label>
                            <input
                              type="text"
                              className={inputCls}
                              value={customer.first_name || ""}
                              autoComplete="off"
                              onChange={(e) =>
                                changeCustomerValue({
                                  customer: row,
                                  name: "first_name",
                                  value: e.target.value,
                                })
                              }
                            />
                          </div>
                          <div>
                            <label className={labelCls}>
                              Last Name {row === 0 && req}
                            </label>
                            <input
                              type="text"
                              className={inputCls}
                              value={customer.last_name || ""}
                              autoComplete="off"
                              onChange={(e) =>
                                changeCustomerValue({
                                  customer: row,
                                  name: "last_name",
                                  value: e.target.value,
                                })
                              }
                            />
                          </div>
                        </div>

                        <div className="tw-mt-4 tw-grid tw-grid-cols-1 tw-gap-4 md:tw-grid-cols-2">
                          <div>
                            <label className={labelCls}>Date of Birth</label>
                            <div className="tw-grid tw-grid-cols-3 tw-gap-2">
                              <select
                                className={inputCls}
                                value={customer.dob_day || 0}
                                onChange={(e) =>
                                  changeCustomerValue({
                                    customer: row,
                                    name: "dob_day",
                                    value: e.target.value,
                                  })
                                }
                              >
                                <option value="0">Day</option>
                                {[...Array(31)].map((_, i) => (
                                  <option key={i + 1} value={i + 1}>
                                    {i + 1}
                                  </option>
                                ))}
                              </select>
                              <select
                                className={inputCls}
                                value={customer.dob_month || 0}
                                onChange={(e) =>
                                  changeCustomerValue({
                                    customer: row,
                                    name: "dob_month",
                                    value: e.target.value,
                                  })
                                }
                              >
                                <option value="0">Month</option>
                                {[
                                  "January",
                                  "February",
                                  "March",
                                  "April",
                                  "May",
                                  "June",
                                  "July",
                                  "August",
                                  "September",
                                  "October",
                                  "November",
                                  "December",
                                ].map((month, i) => (
                                  <option key={i + 1} value={i + 1}>
                                    {month}
                                  </option>
                                ))}
                              </select>
                              <select
                                className={inputCls}
                                value={customer.dob_year || 0}
                                onChange={(e) =>
                                  changeCustomerValue({
                                    customer: row,
                                    name: "dob_year",
                                    value: e.target.value,
                                  })
                                }
                              >
                                <option value="0">Year</option>
                                {Array.from(
                                  { length: 100 },
                                  (_, i) => new Date().getFullYear() - i,
                                ).map((y) => (
                                  <option key={y} value={y}>
                                    {y}
                                  </option>
                                ))}
                              </select>
                            </div>
                          </div>
                          <div>
                            <label className={labelCls}>Nationality</label>
                            <Select<SelectOption>
                              instanceId={`nationality-${row}`}
                              inputId={`nationality-${row}`}
                              styles={bookingSelectStyles}
                              menuPortalTarget={portalTarget}
                              menuPosition="fixed"
                              options={nationalityOptions}
                              value={
                                nationalityOptions.find(
                                  (o) =>
                                    String(o.value) ===
                                    String(customer.nationality),
                                ) || null
                              }
                              onChange={(opt) =>
                                changeCustomerValue({
                                  customer: row,
                                  name: "nationality",
                                  value: opt ? String(opt.value) : "",
                                })
                              }
                              isClearable
                              placeholder="Select nationality"
                            />
                          </div>
                        </div>

                        <div className="tw-mt-4 tw-grid tw-grid-cols-1 tw-gap-4 md:tw-grid-cols-2">
                          <div>
                            <label className={labelCls}>
                              Phone Number {row === 0 && req}
                            </label>
                            <div className="tw-grid tw-grid-cols-1 tw-gap-2 sm:tw-grid-cols-2">
                              <Select<SelectOption>
                                instanceId={`phone-code-${row}`}
                                inputId={`phone-code-${row}`}
                                styles={bookingSelectStyles}
                                menuPortalTarget={portalTarget}
                                menuPosition="fixed"
                                options={phoneCodeOptions}
                                value={
                                  phoneCodeOptions.find(
                                    (o) =>
                                      String(o.value) ===
                                      String(customer.phone_code),
                                  ) || null
                                }
                                onChange={(opt) =>
                                  changeCustomerValue({
                                    customer: row,
                                    name: "phone_code",
                                    value: opt ? String(opt.value) : "",
                                  })
                                }
                                isClearable
                                placeholder="Country Code"
                              />
                              <input
                                type="text"
                                className={inputCls}
                                value={customer.phone || ""}
                                placeholder="Phone Number"
                                autoComplete="off"
                                onChange={(e) => {
                                  const value = e.target.value.replace(
                                    /\D/g,
                                    "",
                                  );
                                  changeCustomerValue({
                                    customer: row,
                                    name: "phone",
                                    value: value,
                                  });
                                }}
                              />
                            </div>
                          </div>
                          <div>
                            <label className={labelCls}>
                              Email {row === 0 && req}
                            </label>
                            <input
                              type="text"
                              className={inputCls}
                              value={customer.email || ""}
                              autoComplete="off"
                              onChange={(e) =>
                                changeCustomerValue({
                                  customer: row,
                                  name: "email",
                                  value: e.target.value,
                                })
                              }
                            />
                          </div>
                        </div>
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          </>
        )}
      </div>
    </Modal>
  );
}
