"use client";
import { useSearchParams } from "next/navigation";
import { useEffect, useState } from "react";
import Breadcrumb from "@/components/header/breadcrumb";
import { getPaymentDetail } from "@/services/booking/paymentDetail";
import TripDetails from "./sections/trip-details";
import PaymentDetails from "./sections/payment-details";
import TravelerDetails from "./sections/traveler-details";
import Conversation from "./sections/conversation";
import TravelerDetailsModal from "./sections/traveler-details-modal";
import PaymentDetailsModal from "./payment-details-modal";
import Promotions from "./sections/promotions";
import PromoCodeBox from "./PromoCodeBox";
import Attachment from "./sections/attachments";
import StatusSummary from "./sections/status-summary";
import MobileFooterSticky from "./mobile-footer-sticky";
import { pageTitleCls, cardCls, cardTitleCls } from "./ui";
import { primaryBtnCls } from "@/components/tour-detail-page/ui";

export default function Page({ referenceId }: { referenceId: string }) {
  const searchParams = useSearchParams();
  const [detailsLoading, setDetailsLoading] = useState(true);
  const [notFound, setNotFound] = useState(false);
  const [errorType, setErrorType] = useState<"404" | "500" | null>(null);
  const [formErrors, setFormErrors] = useState<{ [key: string]: string[] }>({});
  const [travelerModalOpen, setTravelerModalOpen] = useState(false);
  const [amountModalOpen, setAmountModalOpen] = useState(false);

  const [data, setData] = useState({
    id: 0,
    reference_id: "",
    start_date: "",
    subject: "",
    pax: null,
    token: "",
    booking_status: "",
    booking_status_label: "",
    record_type: "",
    record_type_label: "",
    payment_status: "",
    payment_status_label: "",
    service_type: "",
    service_type_label: "",
    seller_currency: "",
    buyer_currency: "",
    created_at: "",
    company: {
      id: 0,
      name: "",
    },
    amounts: {
      buyer: {
        coupon_amount: 0,
        discount_amount: 0,
        final_amount: 0,
        original_amount: 0,
        paid_amount: 0,
        remaining_amount: 0,
        total_discount: 0,
      },
      seller: {
        coupon_amount: 0,
        discount_amount: 0,
        final_amount: 0,
        original_amount: 0,
        paid_amount: 0,
        remaining_amount: 0,
        total_discount: 0,
      },
    },
    tour: {
      id: 0,
      name: "",
      slug: "",
      image: "",
      start_location: "",
      end_location: "",
      pickup_time: "",
      dropoff_time: "",
      suitable_ages: "",
      duration_days: 0,
      departure_type: "",
      languages: [{ id: 0, name: "" }],
      defaults: { accommodation: false },
      guide_type: { name: { en: "" } },
    },
    items: [],
    travelers: [],
    attachments: [],
    promotions: [],
    applied_promo_code: null as { code: string; discount: number } | null,
  });

  const fetchDetails = async () => {
    try {
      const res = await getPaymentDetail(
        referenceId,
        searchParams.get("token")!,
      );
      setData({
        ...data,
        id: res.data.id,
        reference_id: res.data.reference_id,
        booking_status: res.data.booking_status,
        booking_status_label: res.data.booking_status_label,
        record_type: res.data.record_type,
        record_type_label: res.data.record_type_label,
        payment_status: res.data.payment_status,
        payment_status_label: res.data.payment_status_label,
        start_date: res.data.start_date,
        subject: res.data.subject,
        token: res.data.token,
        pax: res.data.pax,
        service_type: res.data.service_type,
        service_type_label: res.data.service_type_label,
        seller_currency: res.data.seller_currency,
        buyer_currency: res.data.buyer_currency,
        amounts: res.data.amounts,
        created_at: res.data.created_at,
        company: {
          ...data.company,
          id: res.data.company.id,
          name: res.data.company.name,
        },
        tour: {
          ...data.tour,
          id: res.data.tour.id,
          name: res.data.tour.name,
          slug: res.data.tour.slug,
          image: res.data.tour.image,
          start_location: res.data.tour.start_location,
          end_location: res.data.tour.end_location,
          pickup_time: res.data.tour.pickup_time,
          dropoff_time: res.data.tour.dropoff_time,
          suitable_ages: res.data.tour.suitable_ages,
          duration_days: res.data.tour.duration_days,
          departure_type: res.data.tour.departure_type,
          languages: res.data.tour.languages,
          defaults: res.data.tour.defaults,
          guide_type: res.data.tour.guide_type,
        },
        items: res.data.items,
        travelers: res.data.travelers,
        attachments: res.data.attachments,
        promotions: res.data.promotions,
        applied_promo_code: res.data.applied_promo_code ?? null,
      });
      setDetailsLoading(false);
    } catch (error: any) {
      if (error.status === 404) {
        setErrorType("404");
        setNotFound(true);
      } else if (error.status >= 500 || !error.status) {
        setErrorType("500");
        setNotFound(true);
      }
      setDetailsLoading(false);
    }
  };

  useEffect(() => {
    fetchDetails();
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  const shellCls = "tw-mx-auto tw-max-w-[1320px] tw-px-4 tw-py-6 tw-font-display";

  if (detailsLoading)
    return (
      <main>
        <div className={shellCls}>
          <Breadcrumb items={[{ pageTitle: "Booking & Enquiry", pageUrl: "" }]} />
          <div className="tw-flex tw-flex-col tw-items-center tw-gap-4 tw-py-20 tw-text-[#5d556c]">
            <span className="tw-inline-block tw-h-12 tw-w-12 tw-animate-spin tw-rounded-full tw-border-4 tw-border-solid tw-border-[#854ec9] tw-border-r-transparent" />
            <p className="tw-m-0 tw-text-center tw-text-[15px]">
              Loading your order details.
              <br />
              Please wait.
            </p>
          </div>
        </div>
      </main>
    );

  if (notFound && (errorType === "404" || errorType === "500")) {
    const is404 = errorType === "404";
    return (
      <main>
        <div className={shellCls}>
          <div className="tw-mx-auto tw-max-w-[520px] tw-py-16 tw-text-center">
            <div
              className={`tw-mx-auto tw-mb-5 tw-grid tw-h-20 tw-w-20 tw-place-items-center tw-rounded-full ${
                is404 ? "tw-bg-[#fef6e7] tw-text-[#b7791f]" : "tw-bg-[#f4eefc] tw-text-[#854ec9]"
              }`}
            >
              <svg width="40" height="40" fill="currentColor" viewBox="0 0 16 16">
                <path d="M8 15A7 7 0 1 1 8 1a7 7 0 0 1 0 14zm0 1A8 8 0 1 0 8 0a8 8 0 0 0 0 16z" />
                <path d="M7.002 11a1 1 0 1 1 2 0 1 1 0 0 1-2 0zM7.1 4.995a.905.905 0 1 1 1.8 0l-.35 3.507a.552.552 0 0 1-1.1 0L7.1 4.995z" />
              </svg>
            </div>
            <h2 className="tw-mb-2 tw-text-[22px] tw-font-bold tw-text-[#14101c]">
              {is404 ? "404 - Record Not Found" : "Oops! Something Went Wrong"}
            </h2>
            <p className="tw-mb-5 tw-text-[14px] tw-text-[#6b6577]">
              {is404 ? (
                <>
                  You may have incorrect access information.
                  <br />
                  If you think this is an error, please contact our support team.
                </>
              ) : (
                <>
                  We&apos;re sorry, but we encountered a temporary issue while
                  loading this page.
                  <br />
                  Please try again in a moment or contact our support team if the
                  problem persists.
                </>
              )}
            </p>
            <a href="/" className={primaryBtnCls}>
              Return to Homepage
            </a>
          </div>
        </div>
      </main>
    );
  }

  return (
    <main>
      <div className={shellCls}>
        <Breadcrumb
          items={[
            { pageTitle: "Booking & Enquiry", pageUrl: "" },
            { pageTitle: data.subject, pageUrl: "" },
          ]}
        />
        <h1 className={`${pageTitleCls} tw-mt-2`}>Your service details</h1>
        <p className="tw-mb-5 tw-mt-1 tw-text-[14px] tw-text-[#6b6577]">
          {data.subject}
        </p>

        <div className="tw-grid tw-grid-cols-1 tw-gap-5 lg:tw-grid-cols-12">
          <div className="tw-order-2 lg:tw-order-1 lg:tw-col-span-3">
            <TripDetails data={data} referenceId={referenceId} />

            {Object.keys(formErrors).length > 0 && (
              <div className="tw-mb-4 tw-rounded-[10px] tw-bg-[#fdecec] tw-px-4 tw-py-3 tw-text-[13.5px] tw-text-[#b23838]">
                <p className="tw-m-0 tw-mb-1 tw-font-semibold">
                  Please check the following errors:
                </p>
                <ul className="tw-m-0 tw-pl-4">
                  {Object.entries(formErrors).map(([field, errors]) =>
                    errors.map((error, index) => (
                      <li key={`${field}-${index}`}>{error}</li>
                    )),
                  )}
                </ul>
              </div>
            )}
          </div>

          <div className="tw-order-1 lg:tw-order-2 lg:tw-col-span-6">
            <StatusSummary data={data} />
            <Conversation referenceId={referenceId} token={data.token} />
          </div>

          <div className="tw-order-3 lg:tw-col-span-3">
            <PaymentDetails
              data={data}
              referenceId={referenceId}
              onViewDetails={() => setAmountModalOpen(true)}
            />
            {/* Ödeme yapılmamışsa müşteri genel bir kampanya kodu girebilir; tutarlar
                sunucuda yeniden hesaplandığı için ekran tazelenir. */}
            {data.amounts.buyer.paid_amount <= 0 && data.token && (
              <div className={`${cardCls} tw-mb-4 tw-p-5 tw-font-display`}>
                <h5 className={`${cardTitleCls} tw-mb-1 tw-text-center`}>
                  Promo Code
                </h5>
                <PromoCodeBox
                  referenceId={referenceId}
                  token={data.token}
                  applied={data.applied_promo_code}
                  currency={data.buyer_currency}
                  onAmounts={() => fetchDetails()}
                />
              </div>
            )}
            {data.promotions.length > 0 && (
              <Promotions data={data} referenceId={referenceId} />
            )}
            <TravelerDetails
              data={data}
              onOpenModal={() => setTravelerModalOpen(true)}
            />
            <Attachment data={data} referenceId={referenceId} />
          </div>
        </div>

        <TravelerDetailsModal
          data={data}
          open={travelerModalOpen}
          onClose={() => setTravelerModalOpen(false)}
        />
        <PaymentDetailsModal
          data={data}
          open={amountModalOpen}
          onClose={() => setAmountModalOpen(false)}
        />
      </div>
      <MobileFooterSticky
        data={data}
        onViewDetails={() => setAmountModalOpen(true)}
      />
    </main>
  );
}
