import { cardCls, cardTitleCls } from "../ui";
import { outlineBtnCls } from "@/components/tour-detail-page/ui";

export default function TravelerDetails({
  data,
  onOpenModal,
}: {
  data: any;
  onOpenModal: () => void;
}) {
  const travelers = Array.isArray(data?.travelers) ? data.travelers : [];

  return (
    <div className={`${cardCls} tw-mb-4 tw-p-5 tw-font-display`}>
      <h5 className={`${cardTitleCls} tw-mb-3 tw-text-center`}>Traveller(s)</h5>
      {travelers.length === 0 ? (
        <div className="tw-py-3 tw-text-center tw-text-[13.5px] tw-text-[#8a8398]">
          No travelers are available right now.
        </div>
      ) : (
        <>
          <div className="tw-max-h-[200px] tw-overflow-y-auto">
            <ol className="tw-m-0 tw-flex tw-list-decimal tw-flex-col tw-gap-1 tw-pl-5 tw-text-[14px] tw-text-[#3f3a4d]">
              {travelers.map((customer: any, row: number) => {
                const fullName = `${customer.first_name || ""} ${
                  customer.last_name || ""
                }`.trim();
                return <li key={row}>{fullName || "-"}</li>;
              })}
            </ol>
          </div>
          <button
            type="button"
            onClick={onOpenModal}
            className={`${outlineBtnCls} tw-mt-3 tw-w-full`}
          >
            All Travelers Details
          </button>
        </>
      )}
    </div>
  );
}
